const shuffleContextChoices = (items = []) => {
    const next = Array.isArray(items) ? [...items] : [];
    for (let index = next.length - 1; index > 0; index -= 1) {
        const swapIndex = Math.floor(Math.random() * (index + 1));
        [next[index], next[swapIndex]] = [next[swapIndex], next[index]];
    }
    return next;
};

const normalizeContextSentence = (value) => String(value || '')
    .replace(/\s+([.,!?])/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();

const buildContextStageQuestions = (stageId, hintText, rawRows = '') => (
    String(rawRows || '')
        .split('\n')
        .map((row) => String(row || '').trim())
        .filter((row) => /^\d+\./.test(row))
        .map((row, index) => {
            const normalized = row.replace(/^\d+\.\s*/, '').trim();
            const optionMatch = normalized.match(/\(([^()]*)\)\s*$/);
            const statement = optionMatch ? normalized.slice(0, optionMatch.index).trim() : normalized;
            const answerMatch = statement.match(/\[\s*([^\]]+?)\s*\]/);
            const distractors = optionMatch
                ? optionMatch[1]
                    .split(/\s*,\s*/)
                    .map((item) => item.trim())
                    .filter(Boolean)
                    .slice(0, 2)
                : [];
            if (!answerMatch || distractors.length < 2) return null;
            const answer = answerMatch[1].trim();
            const promptText = normalizeContextSentence(
                statement.replace(/\[\s*([^\]]+?)\s*\]/, '____')
            );
            const sentence = normalizeContextSentence(
                statement.replace(/\[\s*([^\]]+?)\s*\]/, answer)
            );
            return {
                id: `${stageId}-q-${String(index + 1).padStart(2, '0')}`,
                promptText,
                sentence,
                word: answer,
                answer,
                hintText: String(hintText || '').trim(),
                choices: shuffleContextChoices([answer, ...distractors]).map((value, choiceIndex) => ({
                    id: `${stageId}-choice-${index}-${choiceIndex}`,
                    value
                }))
            };
        })
        .filter(Boolean)
);

